begin;
create extension if not exists pgtap;
select plan(7);
insert into auth.users (id,email) values ('b2000000-0000-4000-8000-000000000010','stale@test.local');
insert into public.roles (id,name,slug,permissions) values ('b2000000-0000-4000-8000-000000000011','Stale owner','stale-owner',array['event.edit']);
insert into public.organizations (id,name,slug,status,timezone) values ('b2000000-0000-4000-8000-000000000012','Stale org','stale-org','active','UTC');
insert into public.users (id,auth_user_id,email,display_name) values ('b2000000-0000-4000-8000-000000000013','b2000000-0000-4000-8000-000000000010','stale@test.local','Stale owner');
insert into public.profiles (id,user_id,organization_id,role_id,display_name) values ('b2000000-0000-4000-8000-000000000014','b2000000-0000-4000-8000-000000000013','b2000000-0000-4000-8000-000000000012','b2000000-0000-4000-8000-000000000011','Stale owner');
insert into public.events (id,organization_id,name,event_type,status,start_at,timezone,venue,operational_model) values ('b2000000-0000-4000-8000-000000000015','b2000000-0000-4000-8000-000000000012','Stale event','nightlife','published','2026-09-10T20:00:00Z','UTC','Stale venue','mixed');
insert into public.reporting_destinations (id,organization_id,event_id,spreadsheet_id) values ('b2000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000012','b2000000-0000-4000-8000-000000000015','stale-sheet');
insert into public.reporting_outbox (id,destination_id,organization_id,event_id,requested_sequence,status,available_at) values ('b2000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000012','b2000000-0000-4000-8000-000000000015',1,'pending',now());
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select ok((select count(*)=1 from public.claim_reporting_sync_work('stale-a',1)),'first worker claims');
select ok((select count(*)=0 from public.claim_reporting_sync_work('stale-b',1)),'unexpired lease is not reclaimed');
update public.reporting_outbox set locked_at=now()-interval '6 minutes' where id='b2000000-0000-4000-8000-000000000002';
select ok((select count(*)=1 from public.claim_reporting_sync_work('stale-b',1)),'expired lease is reclaimed');
select is((select status from public.reporting_sync_runs where attempt=1 and destination_id='b2000000-0000-4000-8000-000000000001'),'failed','old run is finalized');
select is((select error_code from public.reporting_sync_runs where attempt=1 and destination_id='b2000000-0000-4000-8000-000000000001'),'worker_lease_expired','stale error is sanitized');
select ok((select status='processing' and attempts=2 and active_sync_run_id is not null from public.reporting_outbox where id='b2000000-0000-4000-8000-000000000002'),'new lease is active');
select ok((select count(*)=1 from public.reporting_sync_runs where status='failed' and finished_at is not null and destination_id='b2000000-0000-4000-8000-000000000001'),'stale run is terminal');
select * from finish();
rollback;
